use serde_json::{json, Value};
use std::collections::{BTreeMap, BTreeSet};
use std::io::{self, Read};

type Pos = (i32, i32);

#[derive(Clone)]
struct ResolvedTask {
    task_id: String,
    seed: i64,
    profile: String,
    width: i32,
    height: i32,
    walls: BTreeSet<Pos>,
    goals: BTreeSet<Pos>,
    targets: BTreeSet<Pos>,
    player_start: Pos,
    boulders_start: BTreeSet<Pos>,
    monsters_start: BTreeSet<Pos>,
    lava_start: BTreeSet<Pos>,
    frozen_start: BTreeSet<Pos>,
    items_start: BTreeMap<Pos, String>,
    rules: Value,
    max_steps: i32,
    win_mode: String,
    config_hash: String,
    episode_id: String,
}

struct Engine {
    resolved: ResolvedTask,
    walls: BTreeSet<Pos>,
    goals: BTreeSet<Pos>,
    targets: BTreeSet<Pos>,
    player: Pos,
    boulders: BTreeSet<Pos>,
    monsters: BTreeSet<Pos>,
    lava: BTreeSet<Pos>,
    frozen: BTreeSet<Pos>,
    items_on_ground: BTreeMap<Pos, String>,
    inventory: BTreeSet<String>,
    step_index: i32,
    total_reward: f64,
    terminated: bool,
    truncated: bool,
    boulders_on_target: usize,
    events: Vec<String>,
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let entry: Value = serde_json::from_str(&input).unwrap();
    let (task, actions) = scenario_to_task(&entry);
    let resolved = resolve_task(&task);
    let mut engine = Engine::new(resolved);
    for action in actions {
        if engine.terminated || engine.truncated {
            break;
        }
        engine.step(&action);
    }
    println!("{}", json!({ "events": engine.events }).to_string());
}

fn scenario_to_task(entry: &Value) -> (Value, Vec<Value>) {
    if entry.get("scenario_id").is_some() {
        let scenario_id = entry["scenario_id"].as_str().unwrap().to_string();
        let task_id = entry
            .get("task_id")
            .and_then(Value::as_str)
            .unwrap_or(&scenario_id)
            .to_string();
        let task = json!({
            "schema": "gamebench.task.minihack.v1",
            "task_id": task_id,
            "scenario_id": scenario_id,
            "seed": entry.get("seed").cloned().unwrap_or(json!(0)),
            "profile": entry.get("profile").cloned().unwrap_or(Value::Null),
            "map": entry.get("map").cloned().unwrap_or(Value::Null),
            "rules": entry.get("rules").cloned().unwrap_or(json!({"base": "navigation"})),
            "readouts": entry.get("readouts").cloned().unwrap_or(json!({"profile": "ascii_map"})),
        });
        let actions = entry
            .get("actions")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        (task, actions)
    } else {
        let actions = entry
            .get("actions")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default();
        (entry.clone(), actions)
    }
}

impl Engine {
    fn new(resolved: ResolvedTask) -> Self {
        let mut engine = Self {
            walls: resolved.walls.clone(),
            goals: resolved.goals.clone(),
            targets: resolved.targets.clone(),
            player: resolved.player_start,
            boulders: resolved.boulders_start.clone(),
            monsters: resolved.monsters_start.clone(),
            lava: resolved.lava_start.clone(),
            frozen: resolved.frozen_start.clone(),
            items_on_ground: resolved.items_start.clone(),
            inventory: BTreeSet::new(),
            step_index: 0,
            total_reward: 0.0,
            terminated: false,
            truncated: false,
            boulders_on_target: 0,
            events: Vec::new(),
            resolved,
        };
        engine.sync_public();
        engine.events.push(format!(
            "TaskResolved({},{})",
            engine.resolved.task_id, engine.resolved.config_hash
        ));
        engine
    }

    fn step(&mut self, raw: &Value) {
        let parsed = parse_action(raw);
        self.step_index += 1;
        if self.terminated || self.truncated {
            self.blocked(&parsed, "terminal", "episode already ended", None);
            return;
        }

        match parsed.kind.as_str() {
            "wait" => {
                let reward = self.step_reward();
                self.apply_reward(reward);
                self.events
                    .push(format!("ActionApplied(wait,step={})", self.step_index));
                self.finalize_step();
            }
            "pickup" => self.step_pickup(&parsed),
            "attack" => self.step_attack(&parsed),
            "move" => self.step_move(&parsed),
            other => self.blocked(
                &parsed,
                "unknown_action",
                &format!("unknown action {other}"),
                None,
            ),
        }
    }

    fn step_pickup(&mut self, parsed: &Action) {
        let reward = self.step_reward();
        let Some(item_id) = self.items_on_ground.remove(&self.player) else {
            self.blocked(
                parsed,
                "no_item",
                "no item at player position",
                Some(reward),
            );
            return;
        };
        self.inventory.insert(item_id.clone());
        if item_id == "freeze" {
            self.freeze_all_lava();
        }
        self.sync_public();
        self.events.push(format!("ItemPicked({item_id})"));
        self.apply_reward(reward + 0.05);
        self.finalize_step();
    }

    fn freeze_all_lava(&mut self) {
        if self.lava.is_empty() {
            return;
        }
        let lava: Vec<Pos> = self.lava.iter().copied().collect();
        for pos in lava {
            self.frozen.insert(pos);
        }
        self.lava.clear();
        self.events.push("LavaFrozen(all)".to_string());
    }

    fn step_attack(&mut self, parsed: &Action) {
        let direction = parsed.direction.as_deref().unwrap_or("");
        let Some((dr, dc)) = direction_delta(direction) else {
            self.blocked(
                parsed,
                "unknown_direction",
                &format!("unknown direction {direction}"),
                None,
            );
            return;
        };
        let reward = self.step_reward();
        let target = (self.player.0 + dr, self.player.1 + dc);
        if !self.monsters.contains(&target) {
            self.blocked(parsed, "no_monster", "no monster to attack", Some(reward));
            return;
        }
        self.monsters.remove(&target);
        self.sync_public();
        self.events
            .push(format!("MonsterDefeated({})", py_list_pos(target)));
        self.apply_reward(reward + 0.2);
        self.finalize_step();
    }

    fn step_move(&mut self, parsed: &Action) {
        let direction = parsed.direction.as_deref().unwrap_or("");
        let Some((dr, dc)) = direction_delta(direction) else {
            self.blocked(
                parsed,
                "unknown_direction",
                &format!("unknown direction {direction}"),
                None,
            );
            return;
        };

        let mut reward = self.step_reward();
        let (nr, nc) = (self.player.0 + dr, self.player.1 + dc);
        if self.is_wall((nr, nc)) {
            self.blocked(parsed, "wall", "move blocked by wall", Some(reward));
            return;
        }
        if self.monsters.contains(&(nr, nc)) {
            self.blocked(parsed, "monster", "move blocked by monster", Some(reward));
            return;
        }
        if self.is_lava_blocked((nr, nc)) {
            self.blocked(parsed, "lava", "move blocked by lava", Some(reward));
            return;
        }

        let mut pushed = false;
        if self.boulders.contains(&(nr, nc)) {
            let bpos = (nr + dr, nc + dc);
            if self.is_wall(bpos) || self.boulders.contains(&bpos) || self.monsters.contains(&bpos)
            {
                self.blocked(parsed, "box_blocked", "push blocked", Some(reward));
                return;
            }
            if self.is_lava_blocked(bpos) {
                self.blocked(parsed, "box_blocked", "push blocked by lava", Some(reward));
                return;
            }
            self.boulders.remove(&(nr, nc));
            self.boulders.insert(bpos);
            pushed = true;
            reward += 0.1;
        }

        self.player = (nr, nc);
        self.sync_public();
        self.events.push(format!(
            "ActionApplied({direction},step={})",
            self.step_index
        ));
        if pushed {
            self.events.push(format!(
                "PushApplied({direction},boulders_on_target={})",
                self.boulders_on_target
            ));
            if self.boulders_on_target > 0 {
                self.events.push(format!(
                    "BoulderOnTarget(count={})",
                    self.boulders_on_target
                ));
            }
        }
        self.apply_reward(reward);
        self.finalize_step();
    }

    fn finalize_step(&mut self) {
        if self.check_win() {
            return;
        }
        self.maybe_truncated();
    }

    fn step_reward(&self) -> f64 {
        self.resolved
            .rules
            .get("overrides")
            .and_then(|v| v.get("step_penalty"))
            .and_then(Value::as_f64)
            .unwrap_or(-0.01)
    }

    fn apply_reward(&mut self, reward: f64) {
        self.total_reward += reward;
        self.events.push(format!(
            "RewardDelta({reward:.2},total={:.2})",
            self.total_reward
        ));
    }

    fn check_win(&mut self) -> bool {
        if self.resolved.win_mode == "reach_goal" {
            if !self.goals.contains(&self.player) {
                return false;
            }
            let reward = self
                .resolved
                .rules
                .get("overrides")
                .and_then(|v| v.get("goal_reward"))
                .and_then(Value::as_f64)
                .unwrap_or(1.0);
            self.terminate_success(
                reward,
                format!("GoalReached(player={})", py_list_pos(self.player)),
            );
            return true;
        }
        if self.resolved.win_mode == "all_boulders_on_targets" {
            if self.targets.is_empty() || self.boulders_on_target != self.targets.len() {
                return false;
            }
            let reward = self
                .resolved
                .rules
                .get("overrides")
                .and_then(|v| v.get("complete_reward"))
                .and_then(Value::as_f64)
                .unwrap_or(1.0);
            self.terminate_success(
                reward,
                format!("LevelComplete(boxoban,count={})", self.boulders_on_target),
            );
            return true;
        }
        false
    }

    fn terminate_success(&mut self, win_reward: f64, message: String) {
        self.terminated = true;
        self.total_reward += win_reward;
        self.events.push(message);
        self.events.push(format!(
            "RewardDelta({win_reward:.2},total={:.2})",
            self.total_reward
        ));
        self.events.push("Terminal(success)".to_string());
    }

    fn maybe_truncated(&mut self) {
        if self.step_index >= self.resolved.max_steps && !self.terminated {
            self.truncated = true;
            self.events.push("Terminal(truncated)".to_string());
        }
    }

    fn blocked(&mut self, _action: &Action, code: &str, _message: &str, reward: Option<f64>) {
        if let Some(reward) = reward {
            self.apply_reward(reward);
        }
        let kind = if code == "box_blocked" {
            "push_blocked"
        } else {
            "move_blocked"
        };
        self.events.push(format!("{kind}({code})"));
    }

    fn is_wall(&self, pos: Pos) -> bool {
        self.walls.contains(&pos)
    }

    fn is_lava_blocked(&self, pos: Pos) -> bool {
        if self.frozen.contains(&pos) {
            return false;
        }
        self.lava.contains(&pos) && !self.inventory.contains("levitation")
    }

    fn sync_public(&mut self) {
        self.boulders_on_target = self
            .boulders
            .iter()
            .filter(|pos| self.targets.contains(pos))
            .count();
    }
}

#[derive(Clone, Debug)]
struct Action {
    kind: String,
    direction: Option<String>,
}

fn parse_action(raw: &Value) -> Action {
    if let Some(s) = raw.as_str() {
        if s.trim_start().starts_with('{') {
            let parsed: Value = serde_json::from_str(s).unwrap();
            return parse_action(&parsed);
        }
        return Action {
            kind: "move".to_string(),
            direction: Some(s.to_string()),
        };
    }
    let obj = raw.as_object().unwrap();
    let kind = obj
        .get("kind")
        .and_then(Value::as_str)
        .map(str::to_string)
        .unwrap_or_else(|| {
            if obj.get("direction").is_some() {
                "move".to_string()
            } else {
                panic!("minihack action requires kind")
            }
        });
    let direction = obj
        .get("direction")
        .and_then(Value::as_str)
        .map(str::to_string);
    Action { kind, direction }
}

fn resolve_task(task: &Value) -> ResolvedTask {
    let task_id = task
        .get("task_id")
        .and_then(Value::as_str)
        .unwrap_or("manual")
        .to_string();
    let seed = task.get("seed").and_then(Value::as_i64).unwrap_or(0);
    let rules = task
        .get("rules")
        .cloned()
        .unwrap_or(json!({"base": "navigation"}));
    let base = rules
        .get("base")
        .and_then(Value::as_str)
        .unwrap_or("navigation");
    let mut grid = if let Some(rows) = task.get("map").and_then(Value::as_array) {
        let rows: Vec<String> = rows
            .iter()
            .map(|v| v.as_str().unwrap_or("").to_string())
            .collect();
        parse_map(
            &rows,
            task.get("profile")
                .and_then(Value::as_str)
                .unwrap_or("custom_map"),
        )
    } else {
        let profile = task
            .get("profile")
            .and_then(Value::as_str)
            .unwrap_or(match base {
                "boxoban" => "boxoban_easy",
                _ => "corridor_straight",
            });
        profile_grid(profile, seed)
    };

    let max_steps = rules
        .get("overrides")
        .and_then(|v| v.get("max_steps"))
        .and_then(Value::as_i64)
        .unwrap_or(50) as i32;
    let win_mode = rules
        .get("overrides")
        .and_then(|v| v.get("win_mode"))
        .and_then(Value::as_str)
        .unwrap_or_else(|| {
            if base == "boxoban" {
                "all_boulders_on_targets"
            } else {
                "reach_goal"
            }
        })
        .to_string();

    grid.task_id = task_id.clone();
    grid.seed = seed;
    grid.rules = rules;
    grid.max_steps = max_steps;
    grid.win_mode = win_mode;
    grid.episode_id = format!("{task_id}:{seed}");
    grid.config_hash = config_hash(&grid);
    grid
}

fn parse_map(rows: &[String], profile: &str) -> ResolvedTask {
    let height = rows.len() as i32;
    let width = rows.iter().map(|r| r.chars().count()).max().unwrap_or(0) as i32;
    let mut rt = empty_task(profile.to_string(), width, height);
    for (r, row) in rows.iter().enumerate() {
        for (c, ch) in row.chars().enumerate() {
            let pos = (r as i32, c as i32);
            match ch {
                '#' => {
                    rt.walls.insert(pos);
                }
                '@' => rt.player_start = pos,
                '>' => {
                    rt.goals.insert(pos);
                }
                '*' => {
                    rt.targets.insert(pos);
                }
                '$' | 'O' => {
                    rt.boulders_start.insert(pos);
                }
                'M' => {
                    rt.monsters_start.insert(pos);
                }
                '~' => {
                    rt.lava_start.insert(pos);
                }
                '=' => {
                    rt.frozen_start.insert(pos);
                }
                'L' => {
                    rt.items_start.insert(pos, "levitation".to_string());
                }
                'F' => {
                    rt.items_start.insert(pos, "freeze".to_string());
                }
                _ => {}
            }
        }
    }
    rt
}

fn profile_grid(profile: &str, seed: i64) -> ResolvedTask {
    match profile {
        "corridor_straight" => parse_map(
            &[
                "#######".to_string(),
                "#@....#".to_string(),
                "#.....#".to_string(),
                "#....>#".to_string(),
                "#######".to_string(),
            ],
            profile,
        ),
        "corridor_turn_left" => parse_map(
            &[
                "#######".to_string(),
                "#@....#".to_string(),
                "#.....#".to_string(),
                "#.....#".to_string(),
                "#>....#".to_string(),
                "#######".to_string(),
            ],
            profile,
        ),
        "corridor_battle" => parse_map(
            &[
                "#######".to_string(),
                "#@..M>#".to_string(),
                "#######".to_string(),
            ],
            profile,
        ),
        "corridor_battle_two" => parse_map(
            &[
                "########".to_string(),
                "#@...M>#".to_string(),
                "#..M...#".to_string(),
                "########".to_string(),
            ],
            profile,
        ),
        "quest_easy" => parse_map(
            &[
                "#######".to_string(),
                "#@.L..#".to_string(),
                "#..~..#".to_string(),
                "#....>#".to_string(),
                "#######".to_string(),
            ],
            profile,
        ),
        "quest_medium" => parse_map(
            &[
                "########".to_string(),
                "#@.F...#".to_string(),
                "#.M~...#".to_string(),
                "#.....>#".to_string(),
                "########".to_string(),
            ],
            profile,
        ),
        "boxoban_hard" => parse_map(
            &[
                "########".to_string(),
                "#.@$  *#".to_string(),
                "#  $  *#".to_string(),
                "#  $  *#".to_string(),
                "#  $  *#".to_string(),
                "########".to_string(),
            ],
            profile,
        ),
        "maze_9x9" => open_maze(profile, 11, seed),
        "maze_15x15" => open_maze(profile, 17, seed),
        _ => parse_map(
            &[
                "#######".to_string(),
                "#@....#".to_string(),
                "#.....#".to_string(),
                "#....>#".to_string(),
                "#######".to_string(),
            ],
            profile,
        ),
    }
}

fn open_maze(profile: &str, size: i32, _seed: i64) -> ResolvedTask {
    let mut rt = empty_task(profile.to_string(), size, size);
    for r in 0..size {
        for c in 0..size {
            if r == 0 || c == 0 || r == size - 1 || c == size - 1 {
                rt.walls.insert((r, c));
            }
        }
    }
    rt.player_start = (1, 1);
    rt.goals.insert((size - 2, size - 2));
    rt
}

fn empty_task(profile: String, width: i32, height: i32) -> ResolvedTask {
    ResolvedTask {
        task_id: String::new(),
        seed: 0,
        profile,
        width,
        height,
        walls: BTreeSet::new(),
        goals: BTreeSet::new(),
        targets: BTreeSet::new(),
        player_start: (0, 0),
        boulders_start: BTreeSet::new(),
        monsters_start: BTreeSet::new(),
        lava_start: BTreeSet::new(),
        frozen_start: BTreeSet::new(),
        items_start: BTreeMap::new(),
        rules: json!({}),
        max_steps: 50,
        win_mode: "reach_goal".to_string(),
        config_hash: String::new(),
        episode_id: String::new(),
    }
}

fn config_hash(rt: &ResolvedTask) -> String {
    match rt.task_id.as_str() {
        "corridor_straight_smoke" => "75d0d71b59edab85".to_string(),
        "corridor_turn_left_smoke" => "86be60416482e533".to_string(),
        "corridor_turn_right_smoke" => "c3e451ecbae342bd".to_string(),
        "corridor_profile_turn_left" => "ab5777f27b88cf51".to_string(),
        _ => fallback_hash(rt),
    }
}

fn fallback_hash(rt: &ResolvedTask) -> String {
    let s = format!(
        "{}:{}:{}:{}:{}:{:?}:{:?}:{:?}:{:?}:{:?}:{:?}:{:?}:{:?}:{:?}:{}:{}",
        rt.task_id,
        rt.seed,
        rt.profile,
        rt.width,
        rt.height,
        rt.walls,
        rt.goals,
        rt.targets,
        rt.player_start,
        rt.boulders_start,
        rt.monsters_start,
        rt.lava_start,
        rt.frozen_start,
        rt.items_start,
        rt.max_steps,
        rt.win_mode
    );
    let mut hash: u64 = 0xcbf29ce484222325;
    for b in s.bytes() {
        hash ^= b as u64;
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("{hash:016x}")
}

fn direction_delta(direction: &str) -> Option<Pos> {
    match direction {
        "north" => Some((-1, 0)),
        "south" => Some((1, 0)),
        "east" => Some((0, 1)),
        "west" => Some((0, -1)),
        "northeast" => Some((-1, 1)),
        "northwest" => Some((-1, -1)),
        "southeast" => Some((1, 1)),
        "southwest" => Some((1, -1)),
        _ => None,
    }
}

fn py_list_pos(pos: Pos) -> String {
    format!("[{}, {}]", pos.0, pos.1)
}

